se,"s22v08_nombre_no_generado":false,"s22v08_identidad_no_uuid_autoritativa":false,"s22v08_bloquea_reuso_o_mismo_dia":false,"s22v08_exige_nombre_unico":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22v08_evalua_nombre_carga":false,"s22v08_nombre_editable":true,"s22v08_nombre_no_generado":true,"s22v08_identidad_no_uuid_autoritativa":true,"s22v08_bloquea_reuso_o_mismo_dia":true,"s22v08_exige_nombre_unico":true},"esperado":false}]},"hash":"254dfdac78731c639774304aefeeeed950c55680a5b34acc8be18ecbac20e73c","hash_paquete":"98315d23217f71e6d93503c761c1c93953061095223ed4b975c663efcfe0285d","hash_evaluado":"254dfdac78","hash_paquete_10":"98315d2321"},{"codigo":"S22V-C09","legacy_id":626,"legacy_ids":[626],"relacionadas":[],"residual":"","coberturas":[{"legacy_id":626,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"En LF Simula V1 BLOQUEAR fuente fuera NEW_PORTFOLIO_FILE o EXISTING_LOAD_FOR_UPDATE. Archivo nuevo para PRE_OPERATION_SCENARIO_ANALYSIS sobre snapshot sin crear/modificar oferta automáticamente ni cartera operacional. Carga existente SELECTED_LOAD ancla población UPDATE_SCENARIO_FOR_SELECTED_POPULATION, baseline CURRENT_RESOLVABLE_STATE_BY_BUSINESS_IDENTITY, no archivo histórico como verdad actual ni last-upload-wins. Toda simulación snapshot aislado, sin mutación de cartera, ofertas, condiciones o fuente. CONSOLIDATED_CURRENT_PORTFOLIO_V2_OR_LATER solo candidato futuro, DENY_IN_V1; owner APPROVED. Binding pendiente."}],"hechos":["s22v09_evalua_simula_v1","s22v09_fuente_no_autorizada","s22v09_snapshot_no_aislado","s22v09_mutacion_operacional","s22v09_baseline_historico_o_last_upload","s22v09_poblacion_no_anclada"],"paquete":{"tipo":"NUEVA","codigo":"S22V-C09","clave":"s22v_legacy_626","familia":"B2B_PARTNERS","naturaleza":"CONDUCTA","clase":"TRANSVERSAL","alcance":"B2B","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Fuentes y aislamiento de LF Simula V1","descripcion":"En LF Simula V1 BLOQUEAR fuente fuera NEW_PORTFOLIO_FILE o EXISTING_LOAD_FOR_UPDATE. Archivo nuevo para PRE_OPERATION_SCENARIO_ANALYSIS sobre snapshot sin crear/modificar oferta automáticamente ni cartera operacional. Carga existente SELECTED_LOAD ancla población UPDATE_SCENARIO_FOR_SELECTED_POPULATION, baseline CURRENT_RESOLVABLE_STATE_BY_BUSINESS_IDENTITY, no archivo histórico como verdad actual ni last-upload-wins. Toda simulación snapshot aislado, sin mutación de cartera, ofertas, condiciones o fuente. CONSOLIDATED_CURRENT_PORTFOLIO_V2_OR_LATER solo candidato futuro, DENY_IN_V1; owner APPROVED. Binding pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/626","solicitante":"Cristhian / Claude S22-V 2026-11-25"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22v09_evalua_simula_v1"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22v09_fuente_no_autorizada"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22v09_snapshot_no_aislado"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22v09_mutacion_operacional"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22v09_baseline_historico_o_last_upload"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22v09_poblacion_no_anclada"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22v09_evalua_simula_v1":true,"s22v09_fuente_no_autorizada":false,"s22v09_snapshot_no_aislado":false,"s22v09_mutacion_operacional":false,"s22v09_baseline_historico_o_last_upload":false,"s22v09_poblacion_no_anclada":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22v09_evalua_simula_v1":true,"s22v09_fuente_no_autorizada":true,"s22v09_snapshot_no_aislado":false,"s22v09_mutacion_operacional":false,"s22v09_baseline_historico_o_last_upload":false,"s22v09_poblacion_no_anclada":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22v09_evalua_simula_v1":true,"s22v09_fuente_no_autorizada":false,"s22v09_snapshot_no_aislado":true,"s22v09_mutacion_operacional":false,"s22v09_baseline_historico_o_last_upload":false,"s22v09_poblacion_no_anclada":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22v09_evalua_simula_v1":true,"s22v09_fuente_no_autorizada":false,"s22v09_snapshot_no_aislado":false,"s22v09_mutacion_operacional":true,"s22v09_baseline_historico_o_last_upload":false,"s22v09_poblacion_no_anclada":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22v09_evalua_simula_v1":true,"s22v09_fuente_no_autorizada":false,"s22v09_snapshot_no_aislado":false,"s22v09_mutacion_operacional":false,"s22v09_baseline_historico_o_last_upload":true,"s22v09_poblacion_no_anclada":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22v09_evalua_simula_v1":true,"s22v09_fuente_no_autorizada":false,"s22v09_snapshot_no_aislado":false,"s22v09_mutacion_operacional":false,"s22v09_baseline_historico_o_last_upload":false,"s22v09_poblacion_no_anclada":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22v09_evalua_simula_v1":false,"s22v09_fuente_no_autorizada":true,"s22v09_snapshot_no_aislado":true,"s22v09_mutacion_operacional":true,"s22v09_baseline_historico_o_last_upload":true,"s22v09_poblacion_no_anclada":true},"esperado":false}]},"hash":"136846228f641077558f16882f622879a7a9349df6316d4046435f0b811834c5","hash_paquete":"00c5617a04a7a7fbcad2b8a159193cf26cf66aef3f36989baa28af0ac701fdb1","hash_evaluado":"136846228f","hash_paquete_10":"00c5617a04"}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 n:=n+1;
 END LOOP;
 IF n<>jsonb_array_length(packs) OR vectors<>(SELECT coalesce(sum(jsonb_array_length(value->'paquete'->'pruebas')),0) FROM jsonb_array_elements(packs)) THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S22V proposal-only: independent judgment pending';
END $s22$;
COMMIT;
